def get_college_by_no(coll_no: str):
    """Return college details (English + Marathi) given a college number."""
    return college_master.get(str(coll_no), {"COLL_NAME": "", "COLL_NAMEM": ""})

def find_college_by_name(name: str):
    """Search for a college by English or Marathi name (case insensitive)."""
    name = name.strip().lower()
    for k, v in college_master.items():
        if v["COLL_NAME"].lower() == name or v["COLL_NAMEM"].lower() == name:
            return {k: v}
    return {}

